'use client';

import { type ChangeEvent, FormEvent, useEffect, useState } from 'react';
import { ACTIVITY_TYPES, MANUAL_ACTIVITY_TYPES, isManualActivityType, type ActivityDraft, type ActivityType } from '@/lib/activity-types';
import { buildManualPedagogy } from '@/lib/manual-pedagogy';
import { SCENARIO_EXAMPLE_CONTENT, type ScenarioContent, type ScenarioScene } from '@/lib/scenario';
import { DEFAULT_EXTERNAL_GAME_CONTENT, externalResourceEmbedUrl, extractExternalGameUrl, inspectExternalHtml, normalizeExternalGameContent, providerFromExternalGameUrl, providerLabel, type ExternalResourceOutput } from '@/lib/external-games';
import { normalizeVoiceCoachContent, VOICE_ACTIVITY_KINDS, VOICE_COACH_MODES, VOICE_LISTENING_FORMATS, type VoiceActivityKind, type VoiceListeningFormat } from '@/lib/voice-coach';
import { VOICE_SESSION_DURATION_MINUTES } from '@/lib/voice-session-duration';

type Question = { question: string; choices: string[]; correctIndex: number; explanation: string };
type ContentRow = Record<string,unknown>;
type ApiResult<T> = { ok: true; data: T } | { ok: false; error: { message: string } };
type EditableActivity = ActivityDraft & { id: string; status: 'draft' | 'published' };
type ExternalAnalysis = { title:string;theme:string;audience:string;level:'debutant'|'intermediaire'|'avance';difficulty:string;objectives:string[];instructions:string;concepts:string[];introduction:string;preGameExplanation:string;learnerTips:string[];debrief:string;correction:string;summary:string;memo:string;questions:Array<{question:string;answer:string}> };
type PedagogyFrame = { title:string;theme:string;audience:string;level:'debutant'|'intermediaire'|'avance';durationMinutes:number;objectives:string;instructions:string;explanation:string;correction:string };

const manualSymbols: Partial<Record<ActivityType,string>> = { quiz:'?', 'drag-drop':'↕', 'true-false':'✓',scenario:'➜',matching:'⇄',ranking:'≡','revision-cards':'▤','type-answer':'⌨','question-wheel':'✺','live-poll':'◔','external-game':'⌁','voice-coach':'◉' };
const EXTERNAL_OUTPUT_OPTIONS: Array<[ExternalResourceOutput,string]> = [['course','Cours complet'],['summary','Résumé'],['memo','Fiche mémo'],['explanations','Explications pédagogiques'],['quiz','Quiz'],['true-false','Vrai ou faux'],['open-questions','Questions ouvertes'],['scenario','Mise en situation'],['case-study','Étude de cas'],['exercise','Exercice complémentaire'],['correction','Corrigé'],['pdf','Version PDF']];
type VoiceLibraryDocument={id:string;originalName:string;status:string;pageCount?:number|null;detectedTheme?:string|null};
const VOICE_COACH_DEMOS:Array<{label:string;content:Record<string,unknown>}>= [
  {label:'Français professionnel · Accueillir un visiteur',content:{learningLanguage:'français professionnel',professionalTheme:'Accueil et relation client',topic:'Accueillir un visiteur',audience:'Agents d’accueil débutants',activityKinds:['pronunciation','professional-dialogue','branching-conversation'],aiRole:'Visiteur',learnerRole:'Agent d’accueil',professionalContext:'Un visiteur arrive sans rendez-vous et demande à rencontrer un responsable.',mission:'Accueillir, vérifier le motif de la visite, informer le responsable et orienter le visiteur.',objectives:['Utiliser une formule d’accueil professionnelle','Questionner avec courtoisie','Reformuler la demande'],skills:['Écoute active','Questionnement','Orientation'],repeatItems:['Bonjour, que puis-je faire pour vous ?','Pouvez-vous me préciser le nom de la personne que vous souhaitez rencontrer ?'],customQuestions:['Comment accueillez-vous le visiteur ?','Que demandez-vous pour vérifier son rendez-vous ?'],evaluationCriteria:['Courtoisie','Clarté','Reformulation'],difficulty:'progressive'}},
  {label:'Propreté · Client mécontent',content:{learningLanguage:'français professionnel',professionalTheme:'Propreté et hygiène',topic:'Répondre à une réclamation client',audience:'Agents de propreté et chefs d’équipe',activityKinds:['professional-dialogue','branching-conversation','listening-comprehension'],aiRole:'Client mécontent',learnerRole:'Agent de propreté',professionalContext:'Le client signale que le sol de l’accueil présente encore des traces après la prestation.',mission:'Écouter sans interrompre, reformuler, proposer une action et confirmer le suivi.',objectives:['Traiter une réclamation avec professionnalisme','Proposer une solution adaptée'],skills:['Écoute','Reformulation','Recherche de solution'],unexpectedEvents:['Le client demande une intervention immédiate','Le matériel habituel est indisponible'],evaluationCriteria:['Respect du client','Pertinence de la solution','Traçabilité de l’action'],difficulty:'progressive'}},
  {label:'Management · Agent en colère',content:{learningLanguage:'français professionnel',professionalTheme:'Management de proximité',topic:'Recevoir un agent en colère qui refuse une consigne',audience:'Chefs d’équipe',activityKinds:['professional-dialogue','branching-conversation','surprise-roleplay'],aiRole:'Agent en colère',learnerRole:'Chef d’équipe',professionalContext:'Un agent conteste une nouvelle organisation et refuse d’exécuter la consigne devant ses collègues.',mission:'Faire baisser la tension, écouter, rappeler le cadre, rechercher une solution et conclure l’entretien.',objectives:['Conduire un entretien difficile','Rappeler une règle sans humilier','Conclure avec un engagement clair'],skills:['Écoute active','Posture managériale','Gestion de conflit'],unexpectedEvents:['L’agent élève la voix','L’agent évoque une surcharge','L’agent accepte seulement une partie de la solution'],evaluationCriteria:['Qualité de l’écoute','Clarté des consignes','Posture managériale','Qualité de la conclusion'],difficulty:'complexe',randomPools:{characters:['Agent en colère','Salarié démotivé','Agent régulièrement en retard'],missions:['Faire appliquer une consigne','Comprendre le refus','Convenir d’un plan d’action'],contexts:['Entretien individuel','Prise de poste','Après une réclamation client'],difficulties:['Tension élevée','Information incomplète'],events:['L’agent coupe la parole','Un collègue intervient'],durations:['5 minutes','8 minutes']}}},
];

export function ManualActivityDialog({ type,initial,onClose,onCreated }: { type: ActivityType; initial?: EditableActivity | null; onClose: () => void; onCreated: () => void }) {
  const [activityType,setActivityType] = useState<ActivityType>(type);
  const definition = ACTIVITY_TYPES.find(([candidate]) => candidate === activityType)!;
  const [questions,setQuestions] = useState<Question[]>(() => initial ? questionsFromContent(initial.content) : [emptyQuestion()]);
  const [contentJson,setContentJson] = useState(() => JSON.stringify(initial?.content ?? starterContent(type),null,2));
  const [structuredContent,setStructuredContent] = useState<Record<string,unknown>>(() => initial?.content ?? starterContent(type));
  const [scenario,setScenario] = useState<ScenarioContent>(() => initial?.type === 'scenario' ? cloneScenario(initial.content as ScenarioContent) : cloneScenario(SCENARIO_EXAMPLE_CONTENT));
  const [frame,setFrame] = useState<PedagogyFrame>(()=>({title:initial?.title??(type==='scenario'?'Un résident refuse l’entretien de sa chambre':''),theme:initial?.theme??(type==='scenario'?'Relation avec le résident':''),audience:initial?.audience??'',level:initial?.level??'debutant',durationMinutes:initial?.durationMinutes??(type==='scenario'?20:10),objectives:initial?.objectives.join('\n')??(type==='scenario'?'Adapter son intervention à une situation professionnelle\nRespecter la personne, le protocole et la transmission':''),instructions:initial?.instructions??(type==='scenario'?'Lisez chaque situation, choisissez une réaction, validez votre décision puis analysez ses conséquences avant de continuer.':''),explanation:initial?.explanation??'',correction:initial?.correction??''}));
  const [error,setError] = useState(''); const [busy,setBusy] = useState(false);
  const isQuiz = activityType === 'quiz' || activityType === 'tv-quiz';
  const isScenario = activityType === 'scenario';
  const hasGuidedEditor = isManualActivityType(activityType);

  const chooseType = (nextType: ActivityType) => {
    if (initial || nextType === activityType) return;
    const nextContent = starterContent(nextType);
    setActivityType(nextType); setQuestions(questionsFromContent(nextContent)); setStructuredContent(nextContent);
    setScenario(cloneScenario(SCENARIO_EXAMPLE_CONTENT));
    setContentJson(JSON.stringify(nextContent,null,2)); setError('');
  };

  const submit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault(); setBusy(true); setError('');
    try {
      const content = isQuiz ? {...(initial?.content??{}),...quizContent(questions)} : isScenario ? {...(initial?.content??{}),...scenario} : hasGuidedEditor ? structuredContent : JSON.parse(contentJson) as Record<string,unknown>;
      const title = frame.title.trim();
      const objectives = frame.objectives.split('\n').map((item) => item.trim()).filter(Boolean);
      const automatic = buildManualPedagogy(activityType,title,objectives,content);
      const response = await fetch(initial ? `/api/activities/${initial.id}` : '/api/activities',{method:initial ? 'PATCH' : 'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({
        type:activityType,title,theme:frame.theme.trim(),audience:frame.audience.trim(),level:frame.level,objectives,
        durationMinutes:frame.durationMinutes,instructions:frame.instructions.trim(),
        explanation:frame.explanation.trim() || automatic.explanation,
        correction:frame.correction.trim() || automatic.correction,
        sources:initial?.sources ?? [],content,status:initial?.status ?? 'draft',
      })});
      const payload = await response.json() as ApiResult<unknown>;
      if (!payload.ok) throw new Error(payload.error.message);
      onCreated();
    } catch (reason) { setError(reason instanceof Error ? reason.message : 'Enregistrement impossible.'); }
    finally { setBusy(false); }
  };

  return <div className="modal-backdrop" role="dialog" aria-modal="true" aria-labelledby="manual-title"><form className="modal-card studio-card manual-activity-card" onSubmit={submit}>
    <button className="modal-close" type="button" onClick={onClose} aria-label="Fermer">×</button>
    <p className="overline">{initial ? 'Modification' : 'Création manuelle'} · {definition[1]}</p><h2 id="manual-title">{initial ? 'Relire et ajuster l’activité.' : 'Construire l’activité simplement.'}</h2>
    <p>{initial ? 'Corrigez le contenu et les explications avant de publier ou d’animer.' : 'Choisissez un format, renseignez son contenu sans code : le mini-cours, les explications et le corrigé A4 seront composés automatiquement.'}</p>
    {!initial && <section className="manual-format-picker" aria-label="Choisir le format de l’activité"><header><strong>Quel type d’activité souhaitez-vous construire ?</strong><small>Vous pourrez changer de format avant de commencer.</small></header><div>{MANUAL_ACTIVITY_TYPES.map(([candidate,title,copy]) => <button className={activityType === candidate ? 'active' : ''} type="button" onClick={() => chooseType(candidate)} aria-pressed={activityType === candidate} key={candidate}><span>{manualSymbols[candidate] ?? '◇'}</span><b>{title}</b><small>{copy}</small></button>)}</div></section>}
    <section className="manual-section"><div className="manual-section-title"><span>1</span><div><strong>Cadre pédagogique</strong><small>Les informations visibles dans le cours et sur le support imprimé.</small></div></div>
      <div className="form-row"><label>Titre<input name="title" required value={frame.title} onChange={(event)=>setFrame({...frame,title:event.target.value})} placeholder="Ex. Prévenir les risques de chute" /></label><label>Thème<input name="theme" required value={frame.theme} onChange={(event)=>setFrame({...frame,theme:event.target.value})} placeholder="Ex. Sécurité au travail" /></label><label>Durée<input name="durationMinutes" type="number" min="1" max="480" value={frame.durationMinutes} onChange={(event)=>setFrame({...frame,durationMinutes:Number(event.target.value)||1})} required /></label></div>
      <div className="form-row two"><label>Public concerné<input name="audience" value={frame.audience} onChange={(event)=>setFrame({...frame,audience:event.target.value})} placeholder="Ex. Agents de propreté débutants" /></label><label>Niveau<select name="level" value={frame.level} onChange={(event)=>setFrame({...frame,level:event.target.value as PedagogyFrame['level']})}><option value="debutant">Débutant</option><option value="intermediaire">Intermédiaire</option><option value="avance">Avancé</option></select></label></div>
      <label>Objectifs pédagogiques, un par ligne<textarea name="objectives" rows={3} required value={frame.objectives} onChange={(event)=>setFrame({...frame,objectives:event.target.value})} placeholder={'Identifier le risque de chute\nMettre en place un balisage adapté'} /></label>
      <label>Consigne donnée aux participants<textarea name="instructions" rows={2} value={frame.instructions} onChange={(event)=>setFrame({...frame,instructions:event.target.value})} placeholder="Ex. Répondez aux questions puis justifiez chaque choix." /></label>
    </section>

    <section className="manual-section"><div className="manual-section-title"><span>2</span><div><strong>Contenu de l’activité</strong><small>{hasGuidedEditor ? 'Ajoutez les éléments dans le formulaire guidé, sans écrire de code.' : 'Le contenu de ce format reste disponible dans l’éditeur avancé.'}</small></div></div>
      {isQuiz ? <QuizEditor questions={questions} onChange={setQuestions} /> : isScenario ? <ScenarioEditor value={scenario} onChange={setScenario} /> : hasGuidedEditor ? <GuidedActivityEditor type={activityType} value={structuredContent} onChange={setStructuredContent} onExternalAnalysis={(analysis)=>setFrame((current)=>({...current,title:analysis.title||current.title,theme:analysis.theme||current.theme,audience:analysis.audience||current.audience,level:analysis.level||current.level,objectives:analysis.objectives.length?analysis.objectives.join('\n'):current.objectives,instructions:analysis.instructions||current.instructions,explanation:analysis.preGameExplanation||analysis.summary||current.explanation,correction:analysis.correction||current.correction}))} /> : <details className="advanced-editor"><summary>Modifier le contenu du jeu</summary><p>Cette zone avancée conserve la structure nécessaire au fonctionnement du jeu.</p><textarea aria-label="Contenu avancé du jeu" className="code-editor" value={contentJson} onChange={(event) => setContentJson(event.target.value)} rows={12} spellCheck={false} /></details>}
    </section>

    <section className="manual-section automatic-pedagogy"><div className="manual-section-title"><span>3</span><div><strong>Cours et corrigé automatiques</strong><small>Vous pouvez les personnaliser, mais ils ne resteront plus vides.</small></div></div>
      <div className="automatic-note"><span>✓</span><p><strong>Composition automatique activée</strong>Les réponses et vos explications serviront à créer le mini-cours affiché avant le jeu ainsi que le corrigé formateur A4.</p></div>
      <details className="optional-content"><summary>Personnaliser le mini-cours et le corrigé</summary><label>Mini-cours personnalisé<textarea name="explanation" rows={5} value={frame.explanation} onChange={(event)=>setFrame({...frame,explanation:event.target.value})} placeholder="Laissez vide pour composer automatiquement le cours à partir de l’activité." /></label><label>Correction générale personnalisée<textarea name="correction" rows={4} value={frame.correction} onChange={(event)=>setFrame({...frame,correction:event.target.value})} placeholder="Laissez vide pour créer automatiquement les réponses attendues et les critères de réussite." /></label></details>
    </section>
    {error && <p className="form-message error" role="status">{error}</p>}
    <div className="modal-actions manual-actions"><button className="button light" type="button" onClick={onClose}>Annuler</button><button className="button dark" type="submit" disabled={busy}>{busy ? 'Enregistrement…' : initial ? 'Enregistrer les modifications' : 'Créer l’activité et son support A4'}</button></div>
  </form></div>;
}

function QuizEditor({ questions,onChange }: { questions: Question[]; onChange: (questions: Question[]) => void }) {
  const change = (index: number, next: Partial<Question>) => onChange(questions.map((question,questionIndex) => questionIndex === index ? { ...question,...next } : question));
  return <div className="quiz-editor">{questions.map((question,index) => <article className="quiz-question-editor" key={index}>
    <header><span>Question {index + 1}</span>{questions.length > 1 && <button type="button" onClick={() => onChange(questions.filter((_,questionIndex) => questionIndex !== index))}>Supprimer</button>}</header>
    <label>Question<input value={question.question} onChange={(event) => change(index,{question:event.target.value})} required placeholder="Ex. Pourquoi faut-il baliser une zone humide ?" /></label>
    <fieldset><legend>Réponses proposées · cochez la bonne réponse</legend><div className="quiz-choice-editor">{question.choices.map((choice,choiceIndex) => <label className={question.correctIndex === choiceIndex ? 'correct-choice' : ''} key={choiceIndex}><input type="radio" name={`correct-${index}`} checked={question.correctIndex === choiceIndex} onChange={() => change(index,{correctIndex:choiceIndex})} /><span>{String.fromCharCode(65 + choiceIndex)}</span><input aria-label={`Réponse ${choiceIndex + 1}`} value={choice} onChange={(event) => change(index,{choices:question.choices.map((item,itemIndex) => itemIndex === choiceIndex ? event.target.value : item)})} required placeholder={`Réponse ${choiceIndex + 1}`} /></label>)}</div></fieldset>
    <label>Explication après la réponse<textarea rows={3} value={question.explanation} onChange={(event) => change(index,{explanation:event.target.value})} placeholder="Expliquez la règle, donnez un exemple et indiquez le risque évité." /></label>
  </article>)}<button className="add-question" type="button" onClick={() => onChange([...questions,emptyQuestion()])}>＋ Ajouter une question</button></div>;
}

function emptyQuestion(): Question { return { question:'',choices:['','',''],correctIndex:0,explanation:'' }; }
function questionsFromContent(content: unknown): Question[] { const rows = (content as { questions?: Question[] } | null)?.questions; return Array.isArray(rows) && rows.length ? rows.map((row) => ({ question:String(row.question ?? ''),choices:Array.isArray(row.choices) ? row.choices.map(String) : ['','',''],correctIndex:Number(row.correctIndex ?? 0),explanation:String(row.explanation ?? '') })) : [emptyQuestion()]; }
function quizContent(questions: Question[]) { return { questions:questions.map((item) => ({ question:item.question.trim(),choices:item.choices.map((choice) => choice.trim()),correctIndex:item.correctIndex,explanation:item.explanation.trim() })) }; }

function GuidedActivityEditor({ type,value,onChange,onExternalAnalysis }: { type:ActivityType;value:Record<string,unknown>;onChange:(value:Record<string,unknown>)=>void;onExternalAnalysis:(analysis:ExternalAnalysis)=>void }) {
  if (type === 'drag-drop' || type === 'matching') return <DragDropEditor value={value} onChange={onChange} visualAllowed={type === 'drag-drop'} />;
  if (type === 'true-false') return <TrueFalseEditor value={value} onChange={onChange} />;
  if (type === 'ranking') return <RankingEditor value={value} onChange={onChange} />;
  if (type === 'revision-cards') return <RevisionCardsEditor value={value} onChange={onChange} />;
  if (type === 'type-answer') return <TypedPromptsEditor value={value} onChange={onChange} />;
  if (type === 'question-wheel') return <QuestionWheelEditor value={value} onChange={onChange} />;
  if (type === 'live-poll') return <LivePollEditor value={value} onChange={onChange} />;
  if (type === 'external-game') return <ExternalGameEditor value={value} onChange={onChange} onAnalysis={onExternalAnalysis} />;
  if (type === 'voice-coach') return <VoiceCoachEditor value={value} onChange={onChange} />;
  return null;
}

function VoiceCoachEditor({value,onChange}:{value:Record<string,unknown>;onChange:(value:Record<string,unknown>)=>void}) {
  const coach=normalizeVoiceCoachContent(value);
  const [aiBusy,setAiBusy]=useState(false);const [aiMessage,setAiMessage]=useState('');const[documents,setDocuments]=useState<VoiceLibraryDocument[]>([]);
  const update=(patch:Partial<typeof coach>)=>onChange({...coach,...patch});
  const lines=(key:'vocabulary'|'phrases'|'objectives'|'customQuestions'|'repeatItems'|'skills'|'unexpectedEvents'|'evaluationCriteria')=>(event:ChangeEvent<HTMLTextAreaElement>)=>update({[key]:event.target.value.split('\n').map((item)=>item.trim()).filter(Boolean)});
  useEffect(()=>{fetch('/api/files').then(async(response)=>await response.json() as ApiResult<{files:VoiceLibraryDocument[]}>).then((payload)=>{if(payload.ok)setDocuments(payload.data.files.filter((file)=>file.status==='ready'));}).catch(()=>setDocuments([]));},[]);
  const toggleKind=(kind:VoiceActivityKind)=>update({activityKinds:coach.activityKinds.includes(kind)?coach.activityKinds.filter((item)=>item!==kind):[...coach.activityKinds,kind]});
  const toggleFormat=(format:VoiceListeningFormat)=>update({listeningFormats:coach.listeningFormats.includes(format)?coach.listeningFormats.filter((item)=>item!==format):[...coach.listeningFormats,format]});
  const toggleDocument=(document:VoiceLibraryDocument)=>update({sourceDocuments:coach.sourceDocuments.some((item)=>item.id===document.id)?coach.sourceDocuments.filter((item)=>item.id!==document.id):[...coach.sourceDocuments,{id:document.id,name:document.originalName,pages:[]}]});
  const randomLines=(key:keyof typeof coach.randomPools)=>(event:ChangeEvent<HTMLTextAreaElement>)=>update({randomPools:{...coach.randomPools,[key]:event.target.value.split('\n').map((item)=>item.trim()).filter(Boolean)}});
  const applyDemo=(content:Record<string,unknown>)=>onChange(normalizeVoiceCoachContent({...coach,...content}));
  const prepare=async()=>{setAiBusy(true);setAiMessage('');try{const response=await fetch('/api/voice-coach/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:coach})});const payload=await response.json() as ApiResult<{config:Record<string,unknown>;message:string}>;if(!payload.ok)throw new Error(payload.error.message);onChange(payload.data.config);setAiMessage(payload.data.message);}catch(reason){setAiMessage(reason instanceof Error?reason.message:'La préparation IA est indisponible.');}finally{setAiBusy(false);}};
  return <div className="voice-coach-editor">
    <div className="voice-coach-editor-note"><span>◉</span><p><strong>Coach vocal IA · langues et formations professionnelles</strong>Composez une séance avec plusieurs activités. Les anciennes séances restent compatibles et la clé personnelle reste uniquement sur le serveur.</p></div>
    <section className="voice-demo-picker"><strong>Exemples modifiables</strong><div>{VOICE_COACH_DEMOS.map((demo)=><button type="button" onClick={()=>applyDemo(demo.content)} key={demo.label}>{demo.label}</button>)}</div></section>
    <fieldset className="voice-kind-picker"><legend>Activités de la séance · plusieurs choix possibles</legend>{VOICE_ACTIVITY_KINDS.map(([id,label,copy])=><label className={coach.activityKinds.includes(id)?'selected':''} key={id}><input type="checkbox" checked={coach.activityKinds.includes(id)} onChange={()=>toggleKind(id)}/><span><strong>{label}</strong><small>{copy}</small></span></label>)}</fieldset>
    <div className="form-row two"><label>Langue ou domaine travaillé<input required value={coach.learningLanguage} onChange={(event)=>update({learningLanguage:event.target.value})} placeholder="Français professionnel, anglais, propreté, management…"/><small>Champ libre : langues et formations métier.</small></label><label>Langue des explications<input required value={coach.explanationLanguage} onChange={(event)=>update({explanationLanguage:event.target.value})} placeholder="Ex. français"/></label><label>Niveau<input value={coach.cefrLevel} onChange={(event)=>update({cefrLevel:event.target.value})} placeholder="A1, intermédiaire, chef d’équipe confirmé…"/></label><label>Mode général<select value={coach.conversationMode} onChange={(event)=>update({conversationMode:event.target.value as typeof coach.conversationMode})}>{VOICE_COACH_MODES.map(([id,label])=><option value={id} key={id}>{label}</option>)}</select></label></div>
    <div className="form-row two"><label>Grande thématique<input required value={coach.professionalTheme} onChange={(event)=>update({professionalTheme:event.target.value})} placeholder="Ex. Management de proximité"/></label><label>Public concerné<input value={coach.audience} onChange={(event)=>update({audience:event.target.value})} placeholder="Ex. Chefs d’équipe débutants"/></label></div>
    <label>Sujet ou situation<input required value={coach.topic} onChange={(event)=>update({topic:event.target.value})} placeholder="Ex. Recevoir un agent qui refuse une consigne"/></label>
    <div className="form-row two"><label>Rôle joué par l’IA<input value={coach.aiRole} onChange={(event)=>update({aiRole:event.target.value})} placeholder="Client, agent, résident, recruteur…"/></label><label>Rôle de l’apprenant<input value={coach.learnerRole} onChange={(event)=>update({learnerRole:event.target.value})} placeholder="Chef d’équipe, agent d’accueil…"/></label></div>
    <label>Contexte professionnel<textarea rows={4} value={coach.professionalContext} onChange={(event)=>update({professionalContext:event.target.value})} placeholder="Décrivez le lieu, le problème et les informations dont disposent les personnages."/></label>
    <label>Mission de l’apprenant<textarea rows={3} value={coach.mission} onChange={(event)=>update({mission:event.target.value})} placeholder="Écouter, questionner, reformuler, proposer une solution et conclure."/></label>
    <div className="form-row three"><label>Difficulté<select value={coach.difficulty} onChange={(event)=>update({difficulty:event.target.value as typeof coach.difficulty})}><option value="simple">Simple</option><option value="progressive">Progressive</option><option value="complexe">Complexe</option></select></label><label>Nombre de tentatives<input type="number" min="1" max="10" value={coach.maxAttempts} onChange={(event)=>update({maxAttempts:Number(event.target.value)||1})}/></label><label>Durée maximale<select value={coach.maxDurationMinutes} onChange={(event)=>update({maxDurationMinutes:Number(event.target.value)||10})}>{!VOICE_SESSION_DURATION_MINUTES.includes(coach.maxDurationMinutes as (typeof VOICE_SESSION_DURATION_MINUTES)[number])&&<option value={coach.maxDurationMinutes}>{coach.maxDurationMinutes} minutes (actuelle)</option>}{VOICE_SESSION_DURATION_MINUTES.map((minutes)=><option key={minutes} value={minutes}>{minutes} minutes</option>)}</select></label></div>
    <section className="voice-source-editor"><header><span>1</span><div><strong>Mon cours ou mon texte de référence</strong><small>Copiez-collez une ou plusieurs leçons. Le coach vocal se basera en priorité sur ce contenu.</small></div></header><textarea rows={10} value={coach.lessonText} onChange={(event)=>update({lessonText:event.target.value})} placeholder="Collez ici votre cours, votre dialogue, votre fiche de vocabulaire ou le texte que l’apprenant doit travailler…"/></section>
    <details className="voice-document-picker"><summary>Utiliser mes PDF, PNG ou JPEG déjà analysés <span>{coach.sourceDocuments.length} sélectionné(s)</span></summary>{documents.length?<div>{documents.map((document)=><label key={document.id}><input type="checkbox" checked={coach.sourceDocuments.some((item)=>item.id===document.id)} onChange={()=>toggleDocument(document)}/><span><strong>{document.originalName}</strong><small>{document.detectedTheme||'Document pédagogique'}{document.pageCount?` · ${document.pageCount} page(s)`:''}</small></span></label>)}</div>:<p>Aucun document analysé n’est disponible. Importez-le d’abord dans votre base documentaire.</p>}</details>
    <section className="voice-source-editor"><header><span>2</span><div><strong>Mon script de séance</strong><small>Indiquez l’ordre, le rôle du coach et la manière de faire répéter l’apprenant.</small></div></header><textarea rows={6} value={coach.coachScript} onChange={(event)=>update({coachScript:event.target.value})} placeholder={'Ex. 1. Lire la phrase lentement.\n2. Demander à l’apprenant de la répéter.\n3. Corriger un seul point.\n4. Refaire prononcer la phrase.'}/></section>
    <div className="form-row two"><label>Mes questions, une par ligne<textarea rows={7} value={coach.customQuestions.join('\n')} onChange={lines('customQuestions')} placeholder={'Comment vous appelez-vous ?\nQuel est votre métier ?\nPouvez-vous répéter cette phrase ?'}/><small>Elles seront posées dans l’ordre indiqué.</small></label><label>Mots ou phrases à faire répéter, un par ligne<textarea rows={7} value={coach.repeatItems.join('\n')} onChange={lines('repeatItems')} placeholder={'Good morning, how can I help you?\nI would like to make a reservation.'}/><small>Le coach les prononcera puis attendra la répétition.</small></label></div>
    <div className="form-row three"><label>Compétences à travailler<textarea rows={5} value={coach.skills.join('\n')} onChange={lines('skills')} placeholder={'Écoute active\nReformulation\nGestion de conflit'}/></label><label>Événements imprévus<textarea rows={5} value={coach.unexpectedEvents.join('\n')} onChange={lines('unexpectedEvents')} placeholder={'Le client hausse le ton\nLe matériel est indisponible'}/></label><label>Critères d’évaluation<textarea rows={5} value={coach.evaluationCriteria.join('\n')} onChange={lines('evaluationCriteria')} placeholder={'Qualité de l’écoute\nClarté des consignes\nSolution proposée'}/></label></div>
    <fieldset className="voice-listening-picker"><legend>Formats de compréhension orale</legend>{VOICE_LISTENING_FORMATS.map(([id,label])=><label key={id}><input type="checkbox" checked={coach.listeningFormats.includes(id)} onChange={()=>toggleFormat(id)}/>{label}</label>)}</fieldset>
    {coach.activityKinds.includes('surprise-roleplay')&&<details className="voice-surprise-editor" open><summary>Éléments du jeu de rôle surprise</summary><div className="form-row three"><label>Personnages<textarea rows={4} value={coach.randomPools.characters.join('\n')} onChange={randomLines('characters')}/></label><label>Missions<textarea rows={4} value={coach.randomPools.missions.join('\n')} onChange={randomLines('missions')}/></label><label>Contextes<textarea rows={4} value={coach.randomPools.contexts.join('\n')} onChange={randomLines('contexts')}/></label><label>Difficultés<textarea rows={4} value={coach.randomPools.difficulties.join('\n')} onChange={randomLines('difficulties')}/></label><label>Événements<textarea rows={4} value={coach.randomPools.events.join('\n')} onChange={randomLines('events')}/></label><label>Durées<textarea rows={4} value={coach.randomPools.durations.join('\n')} onChange={randomLines('durations')}/></label></div></details>}
    <button className="button light voice-coach-ai-button" type="button" disabled={aiBusy} onClick={()=>void prepare()}>{aiBusy?'Préparation de la séance…':'✦ Compléter mon cours avec l’IA'}</button>{aiMessage&&<p className="form-message" role="status">{aiMessage}</p>}
    <div className="form-row two"><label>Débit<select value={coach.speed} onChange={(event)=>update({speed:event.target.value as typeof coach.speed})}><option value="slow">Lent</option><option value="normal">Normal</option><option value="natural">Naturel</option></select></label><label>Niveau de correction<select value={coach.correctionLevel} onChange={(event)=>update({correctionLevel:event.target.value as typeof coach.correctionLevel})}><option value="light">Léger</option><option value="normal">Normal</option><option value="detailed">Détaillé</option></select></label></div>
    <div className="form-row three"><label>Vocabulaire, un mot par ligne<textarea rows={5} value={coach.vocabulary.join('\n')} onChange={lines('vocabulary')}/></label><label>Phrases cibles, une par ligne<textarea rows={5} value={coach.phrases.join('\n')} onChange={lines('phrases')}/></label><label>Objectifs de la séance<textarea rows={5} value={coach.objectives.join('\n')} onChange={lines('objectives')}/></label></div>
    <div className="form-row two"><label>Voix<select value={coach.voice} onChange={(event)=>update({voice:event.target.value})}><option value="marin">Marin</option><option value="cedar">Cedar</option><option value="coral">Coral</option><option value="sage">Sage</option><option value="shimmer">Shimmer</option><option value="verse">Verse</option></select></label><label>Transcription<select value={coach.transcriptMode} onChange={(event)=>update({transcriptMode:event.target.value as typeof coach.transcriptMode})}><option value="off">Désactivée</option><option value="optional">Au choix de l’apprenant</option><option value="required">Demandée avec consentement</option></select></label></div>
    <div className="scenario-output-checks"><label><input type="checkbox" checked={coach.showText} onChange={(event)=>update({showText:event.target.checked})}/>Afficher la transcription</label><label><input type="checkbox" checked={coach.allowTranslation} onChange={(event)=>update({allowTranslation:event.target.checked})}/>Autoriser la traduction</label><label><input type="checkbox" checked={coach.allowHints} onChange={(event)=>update({allowHints:event.target.checked})}/>Autoriser les aides et indices</label></div>
    <label>Consigne personnalisée du formateur<textarea rows={4} value={coach.trainerPrompt} onChange={(event)=>update({trainerPrompt:event.target.value})} placeholder="Ex. Insister sur les formules de politesse et ne pas introduire de vocabulaire absent du cours."/></label>
    <section className="voice-activity-preview"><header><div><strong>Aperçu modifiable de la séance</strong><small>Corrigez les champs ci-dessus avant l’enregistrement.</small></div><span>{coach.steps.length?`${coach.steps.length} étape(s) préparée(s)`:'À compléter avec l’IA'}</span></header><p><b>{coach.learnerRole}</b> échange avec <b>{coach.aiRole}</b> dans la situation « {coach.topic} ».</p><div>{coach.activityKinds.map((kind)=><span key={kind}>{VOICE_ACTIVITY_KINDS.find(([id])=>id===kind)?.[1]}</span>)}</div>{coach.steps.length>0&&<ol>{coach.steps.map((step,index)=><li key={`${index}-${step.title}`}><strong>{step.title}</strong><small>{step.instructions}{step.sourceDocument?` · Source : ${step.sourceDocument}${step.sourcePage?`, p. ${step.sourcePage}`:''}`:''}</small></li>)}</ol>}</section>
  </div>;
}

function ExternalGameEditor({ value,onChange,onAnalysis }: { value:Record<string,unknown>;onChange:(value:Record<string,unknown>)=>void;onAnalysis:(analysis:ExternalAnalysis)=>void }) {
  const game = normalizeExternalGameContent(value);
  const [rawInput,setRawInput] = useState(game.sourceUrl||game.embedUrl);
  const [inputMode,setInputMode] = useState<'iframe'|'link'|'html'>(game.htmlSourceName ? 'html' : game.sourceUrl||game.embedUrl ? 'link' : 'iframe');
  const [inputError,setInputError] = useState('');
  const [aiBusy,setAiBusy] = useState(false);
  const [uploadBusy,setUploadBusy] = useState(false);
  const [aiMessage,setAiMessage] = useState('');
  const [analysisMethod,setAnalysisMethod] = useState('');
  const update = (patch:Partial<typeof game>) => onChange({...game,...patch});
  const updatePaper = (patch:Partial<typeof game.paper>) => update({paper:{...game.paper,...patch}});
  const acceptInput = (next:string) => {
    setRawInput(next); const url = extractExternalGameUrl(next);
    if (!next.trim()) { setInputError(''); update({sourceUrl:'',embedUrl:'',htmlSourceName:''}); return; }
    if (!url) { setInputError('Seuls un lien HTTPS public ou un iframe contenant une adresse HTTPS sont acceptés. Les scripts et attributs fournis ne sont jamais conservés.'); update({sourceUrl:'',embedUrl:'',htmlSourceName:''}); return; }
    setInputError(''); update({sourceUrl:url,embedUrl:externalResourceEmbedUrl(url),provider:providerFromExternalGameUrl(url),htmlSourceName:''});
  };
  const importHtml=async(event:ChangeEvent<HTMLInputElement>)=>{const file=event.target.files?.[0];event.target.value='';if(!file)return;setAiMessage('');setInputError('');try{if(!/\.html?$/i.test(file.name)&&file.type!=='text/html')throw new Error('Choisissez un fichier HTML au format .html ou .htm.');if(!file.size)throw new Error('Le fichier HTML est vide.');if(file.size>2_000_000)throw new Error('Le fichier HTML dépasse la limite de 2 Mo.');const inspected=inspectExternalHtml(await file.text());if(!inspected)throw new Error('Aucun lien HTTPS intégrable n’a été détecté dans ce fichier. Collez le lien public du jeu ou son code iframe.');const context=[inspected.title?`Titre détecté dans le fichier HTML : ${inspected.title}`:'',inspected.readableText].filter(Boolean).join('\n\n');setRawInput(inspected.sourceUrl);onChange({...game,sourceUrl:inspected.sourceUrl,embedUrl:inspected.embedUrl,provider:inspected.provider,htmlSourceName:file.name,supportText:[game.supportText,context].filter(Boolean).join('\n\n').slice(0,60_000)});setAiMessage(`Le fichier « ${file.name} » a été nettoyé. Vous pouvez maintenant vérifier l’aperçu et lancer l’analyse.`);}catch(reason){setInputError(reason instanceof Error?reason.message:'Lecture du fichier HTML impossible.');}};
  const enrich = async (focus:string[]=['all']) => {
    setAiBusy(true);setAiMessage('');
    try {
      const response=await fetch('/api/external-games/enrich',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sourceUrl:game.sourceUrl||game.embedUrl,description:game.gameDescription,supportText:game.supportText,supportFileIds:game.supportFileIds,selectedOutputs:game.selectedOutputs,focus})});
      const payload=await response.json() as {ok?:boolean;data?:{analysis?:ExternalAnalysis;analysisMethod?:string;message?:string};error?:{message?:string}};
      const result=payload.data?.analysis;
      if(!response.ok||!payload.ok||!result)throw new Error(payload.error?.message||'Analyse impossible.');
      const full=focus.includes('all');
      onChange({...game,gameDescription:full?result.concepts.join('\n'):game.gameDescription,introduction:full||focus.includes('explanations')?result.introduction:game.introduction,preGameExplanation:full||focus.includes('explanations')?result.preGameExplanation:game.preGameExplanation,learnerTips:full||focus.includes('explanations')?result.learnerTips:game.learnerTips,debrief:full||focus.includes('explanations')?result.debrief:game.debrief,summary:full||focus.includes('summary')?result.summary:game.summary,memo:full||focus.includes('summary')?result.memo:game.memo,paper:{...game.paper,questions:full||focus.includes('quiz')||focus.includes('paper')?result.questions:game.paper.questions}});
      if(full||focus.includes('objectives')||focus.includes('explanations'))onAnalysis(result);
      setAnalysisMethod(payload.data?.analysisMethod??'');
      setAiMessage(payload.data?.message||'La partie demandée a été préparée. Relisez-la avant l’enregistrement.');
    } catch(reason) { setAiMessage(reason instanceof Error ? reason.message : 'Génération impossible.'); }
    finally { setAiBusy(false); }
  };
  const uploadSupportFiles=async(event:ChangeEvent<HTMLInputElement>)=>{const files=Array.from(event.target.files??[]);if(!files.length)return;setUploadBusy(true);setAiMessage('');try{const form=new FormData();files.forEach((file)=>form.append('files',file));const response=await fetch('/api/files',{method:'POST',body:form});const payload=await response.json() as {ok?:boolean;data?:{files?:Array<{id:string;name:string}>;errors?:Array<{message:string}>};error?:{message?:string}};const saved=payload.data?.files??[];if(!response.ok||!payload.ok||!saved.length)throw new Error(payload.error?.message||'Import impossible.');update({supportFileIds:[...new Set([...game.supportFileIds,...saved.map((file)=>file.id)])]});setAiMessage(`${saved.length} pièce(s) d’appui ajoutée(s). Vous pouvez relancer l’analyse.`);}catch(reason){setAiMessage(reason instanceof Error?reason.message:'Import impossible.');}finally{setUploadBusy(false);event.target.value='';}};
  const uploadOfficialFile=async(event:ChangeEvent<HTMLInputElement>)=>{const file=event.target.files?.[0];if(!file)return;setUploadBusy(true);setAiMessage('');try{const form=new FormData();form.append('files',file);const response=await fetch('/api/files',{method:'POST',body:form});const payload=await response.json() as {ok?:boolean;data?:{files?:Array<{id:string;name:string}>};error?:{message?:string}};const saved=payload.data?.files?.[0];if(!response.ok||!payload.ok||!saved)throw new Error(payload.error?.message||'Import impossible.');updatePaper({officialFileId:saved.id,officialFileName:saved.name});setAiMessage('Le support d’impression officiel a été importé et associé au jeu.');}catch(reason){setAiMessage(reason instanceof Error?reason.message:'Import impossible.');}finally{setUploadBusy(false);event.target.value='';}};
  const questions=game.paper.questions;
  return <div className="external-game-editor">
    <header className="external-resource-heading"><div><span>⌁</span><div><strong>Ajouter une activité ou une ressource externe</strong><small>Wordwall, YouTube, Vimeo, Genially, LearningApps, Canva, document ou autre application compatible.</small></div></div></header>
    <div className="external-game-security"><span>⌁</span><p><strong>Intégration sécurisée</strong>Seule l’adresse HTTPS validée est conservée. Les scripts, événements et attributs dangereux du code iframe sont bloqués.</p></div>
    <div className="editor-mode-switch three"><button className={inputMode==='iframe'?'active':''} type="button" onClick={()=>setInputMode('iframe')}><span>&lt;/&gt;</span><b>Code iframe</b><small>Collez le code d’intégration fourni par Wordwall ou un autre site.</small></button><button className={inputMode==='link'?'active':''} type="button" onClick={()=>setInputMode('link')}><span>⌁</span><b>Lien du jeu</b><small>Collez directement une adresse HTTPS compatible.</small></button><button className={inputMode==='html'?'active':''} type="button" onClick={()=>setInputMode('html')}><span>HTML</span><b>Fichier HTML</b><small>Importez le fichier fourni par l’application externe.</small></button></div>
    {inputMode==='html'?<label className="external-html-import">Fichier HTML de l’activité<input type="file" accept="text/html,.html,.htm" onChange={(event)=>void importHtml(event)}/><span>{game.htmlSourceName?`✓ ${game.htmlSourceName}`:'Choisir un fichier .html ou .htm · 2 Mo maximum'}</span><small>Le fichier n’est jamais exécuté : seuls son lien HTTPS et son texte utile sont conservés.</small></label>:<label>{inputMode==='iframe'?'Code d’intégration iframe':'Lien HTTPS du jeu'}<textarea required rows={inputMode==='iframe'?4:2} value={rawInput} onChange={(event)=>acceptInput(event.target.value)} placeholder={inputMode==='iframe'?'<iframe src="https://wordwall.net/fr/embed/…"></iframe>':'https://wordwall.net/fr/embed/…'} /></label>}
    {inputMode==='html'&&rawInput&&<label>Adresse HTTPS détectée<input value={rawInput} readOnly/></label>}
    {inputError&&<p className="form-message error" role="status">{inputError}</p>}
    {game.embedUrl&&<section className="external-game-editor-preview"><header><div><small>Aperçu responsive · {providerLabel(game.provider)}</small><strong>{new URL(game.embedUrl).hostname}</strong></div><a href={game.sourceUrl||game.embedUrl} target="_blank" rel="noreferrer">Plein écran ↗</a></header><iframe src={game.embedUrl} title="Aperçu de la ressource externe" loading="lazy" sandbox="allow-scripts allow-forms allow-same-origin allow-popups allow-presentation" allow="fullscreen" allowFullScreen referrerPolicy="strict-origin-when-cross-origin" /></section>}
    <div className="form-row two"><label>Image de présentation, facultative<input type="url" value={game.presentationImageUrl} onChange={(event)=>update({presentationImageUrl:event.target.value})} placeholder="https://…/image.jpg" /></label><label>Mode de validation<select value={game.scoreMode} onChange={(event)=>update({scoreMode:event.target.value==='self_report'?'self_report':'manual_completion'})}><option value="manual_completion">Validation manuelle · activité terminée</option><option value="self_report">L’apprenant indique son score</option></select></label></div>
    {game.scoreMode==='self_report'&&<label>Score maximal annoncé par le jeu<input type="number" min="1" max="10000" value={game.scoreMax} onChange={(event)=>update({scoreMax:Number(event.target.value)||100})} /></label>}
    <label>Description du contenu du jeu<textarea rows={4} value={game.gameDescription} onChange={(event)=>update({gameDescription:event.target.value})} placeholder="Décrivez les notions, les questions, les réponses et le contexte professionnel. L’IA utilisera ce texte si le lien ne peut pas être lu." /></label>
    <details className="external-support-panel" open><summary>Éléments d’appui pour une analyse fiable</summary><p>Si le service bloque la lecture, ajoutez une capture, un PDF, le texte, les questions-réponses ou une transcription. Aucune analyse ne sera inventée.</p><label>Texte, questions-réponses ou transcription<textarea rows={4} value={game.supportText} onChange={(event)=>update({supportText:event.target.value})} placeholder="Collez ici le contenu utile de l’activité ou de la vidéo." /></label><label className="external-official-file">Capture, PDF ou document d’appui<span>{game.supportFileIds.length?`${game.supportFileIds.length} pièce(s) ajoutée(s)`:'PDF, image, Word, PowerPoint ou texte'}</span><input type="file" multiple accept=".pdf,.doc,.docx,.ppt,.pptx,.txt,.png,.jpg,.jpeg" disabled={uploadBusy} onChange={(event)=>void uploadSupportFiles(event)}/><b>{uploadBusy?'Import en cours…':'Ajouter des pièces d’appui'}</b></label></details>
    <fieldset className="external-output-picker"><legend>Contenus à préparer dans cette même création · plusieurs choix possibles</legend>{EXTERNAL_OUTPUT_OPTIONS.map(([output,label])=><label key={output}><input type="checkbox" checked={game.selectedOutputs.includes(output)} onChange={()=>update({selectedOutputs:game.selectedOutputs.includes(output)?game.selectedOutputs.filter((item)=>item!==output):[...game.selectedOutputs,output]})}/>{label}</label>)}</fieldset>
    <div className="external-deliverable-note"><span>✓</span><p><strong>Tout reste regroupé</strong>Le jeu externe, le mini-cours, les explications, les questions et le support PDF A4 sont enregistrés dans la même activité de la bibliothèque.</p></div>
    <div className="external-ai-actions"><button className="button dark" type="button" disabled={aiBusy||!game.sourceUrl} onClick={()=>void enrich()}>{aiBusy?'Analyse en cours…':'✦ Analyser cette ressource'}</button><button type="button" disabled={aiBusy||!game.sourceUrl} onClick={()=>void enrich(['objectives'])}>Générer les objectifs</button><button type="button" disabled={aiBusy||!game.sourceUrl} onClick={()=>void enrich(['explanations'])}>Créer les explications</button><button type="button" disabled={aiBusy||!game.sourceUrl} onClick={()=>void enrich(['quiz'])}>Générer un quiz</button><button type="button" disabled={aiBusy||!game.sourceUrl} onClick={()=>void enrich(['summary'])}>Créer un résumé</button><button type="button" disabled={aiBusy||!game.sourceUrl} onClick={()=>void enrich(['paper'])}>Générer la version papier</button></div>{analysisMethod&&<p className="analysis-method">✓ Analyse fondée sur : {analysisMethod==='support_files'?'les éléments fournis':analysisMethod.replaceAll('_',' ')}.</p>}{aiMessage&&<p className="form-message" role="status">{aiMessage}</p>}
    <div className="form-row two"><label>Introduction<textarea rows={3} value={game.introduction} onChange={(event)=>update({introduction:event.target.value})} placeholder="Présentez le but du jeu et son lien avec la formation." /></label><label>Explication avant le jeu<textarea rows={3} value={game.preGameExplanation} onChange={(event)=>update({preGameExplanation:event.target.value})} placeholder="Rappelez les notions utiles avant de commencer." /></label></div>
    <div className="form-row two"><label>Conseils pour l’apprenant, un par ligne<textarea rows={4} value={game.learnerTips.join('\n')} onChange={(event)=>update({learnerTips:event.target.value.split('\n').map((item)=>item.trim()).filter(Boolean)})} /></label><label>Débriefing après le jeu<textarea rows={4} value={game.debrief} onChange={(event)=>update({debrief:event.target.value})} placeholder="Questions de recul, points à retenir et transfert en situation professionnelle." /></label></div>
    <div className="form-row two"><label>Résumé<textarea rows={4} value={game.summary} onChange={(event)=>update({summary:event.target.value})} placeholder="Résumé directement lié à la ressource." /></label><label>Fiche mémo<textarea rows={4} value={game.memo} onChange={(event)=>update({memo:event.target.value})} placeholder="Points clés, méthode et vigilance." /></label></div>
    <details className="external-paper-editor" open><summary>Version papier associée</summary><p>Cette fiche A4 adapte pédagogiquement le jeu ; elle n’en fait jamais une simple capture ni ne contourne les protections du site externe.</p><div className="external-paper-options"><label><input type="checkbox" checked={game.paper.includeQr} onChange={(event)=>updatePaper({includeQr:event.target.checked})} />Inclure le QR code</label><label><input type="checkbox" checked={game.paper.includeExplanations} onChange={(event)=>updatePaper({includeExplanations:event.target.checked})} />Inclure les explications</label><label><input type="checkbox" checked={game.paper.includeAnswers} onChange={(event)=>updatePaper({includeAnswers:event.target.checked})} />Inclure les réponses</label><label><input type="checkbox" checked={game.paper.includeCorrection} onChange={(event)=>updatePaper({includeCorrection:event.target.checked})} />Inclure le corrigé</label><label><input type="checkbox" checked={game.paper.includeImages} onChange={(event)=>updatePaper({includeImages:event.target.checked})} />Inclure les images</label><label><input type="checkbox" checked={game.paper.learnerVersion} onChange={(event)=>updatePaper({learnerVersion:event.target.checked})} />Version apprenant</label><label><input type="checkbox" checked={game.paper.trainerVersion} onChange={(event)=>updatePaper({trainerVersion:event.target.checked})} />Version formateur avec solutions</label></div><div className="form-row two"><label>Capture d’écran autorisée, facultative<input type="url" value={game.paper.screenshotUrl} onChange={(event)=>updatePaper({screenshotUrl:event.target.value})} placeholder="https://…/capture.jpg" /></label><label>Description ou document source<textarea rows={2} value={game.paper.sourceDescription} onChange={(event)=>updatePaper({sourceDescription:event.target.value})} placeholder="Précisez la source utilisée et les droits dont vous disposez." /></label></div><label className="external-official-file">Fichier d’impression officiellement proposé par le site, facultatif<span>{game.paper.officialFileName||'PDF uniquement · 20 Mo maximum'}</span><input type="file" accept="application/pdf,.pdf" disabled={uploadBusy} onChange={(event)=>void uploadOfficialFile(event)}/><b>{uploadBusy?'Import en cours…':'Choisir un PDF officiel'}</b></label>{game.paper.officialFileId&&<button className="button light external-file-remove" type="button" onClick={()=>updatePaper({officialFileId:'',officialFileName:''})}>Dissocier « {game.paper.officialFileName} »</button>}<div className="external-paper-questions"><header><strong>Questions et réponses pour l’adaptation A4</strong><small>Les réponses servent uniquement au corrigé si vous choisissez de l’inclure.</small></header>{questions.map((row,index)=><article key={index}><span>{index+1}</span><input value={row.question} onChange={(event)=>updatePaper({questions:questions.map((item,itemIndex)=>itemIndex===index?{...item,question:event.target.value}:item)})} placeholder="Question ou exercice" /><input value={row.answer} onChange={(event)=>updatePaper({questions:questions.map((item,itemIndex)=>itemIndex===index?{...item,answer:event.target.value}:item)})} placeholder="Réponse attendue" /><button type="button" onClick={()=>updatePaper({questions:questions.filter((_,itemIndex)=>itemIndex!==index)})}>×</button></article>)}<button className="add-question" type="button" onClick={()=>updatePaper({questions:[...questions,{question:'',answer:''}]})}>＋ Ajouter une question papier</button></div></details>
  </div>;
}

function TrueFalseEditor({ value,onChange }: { value:Record<string,unknown>;onChange:(value:Record<string,unknown>)=>void }) {
  const rows = contentRows(value.statements);
  const update = (index:number,patch:ContentRow) => onChange({...value,statements:rows.map((row,rowIndex) => rowIndex === index ? {...row,...patch} : row)});
  return <div className="simple-editor">{rows.map((row,index) => <article className="simple-editor-card" key={String(row.id ?? index)}><header><strong>Affirmation {index + 1}</strong><button type="button" disabled={rows.length <= 1} onClick={() => onChange({...value,statements:rows.filter((_,rowIndex) => rowIndex !== index)})}>Supprimer</button></header><label>Affirmation<input required value={field(row.text)} onChange={(event) => update(index,{text:event.target.value})} placeholder="Ex. Une zone humide doit toujours être balisée." /></label><fieldset><legend>Bonne réponse</legend><div className="binary-editor-choice"><label className={Boolean(row.answer) ? 'active' : ''}><input type="radio" name={`truth-${index}`} checked={Boolean(row.answer)} onChange={() => update(index,{answer:true})} />Vrai</label><label className={!Boolean(row.answer) ? 'active' : ''}><input type="radio" name={`truth-${index}`} checked={!Boolean(row.answer)} onChange={() => update(index,{answer:false})} />Faux</label></div></fieldset><label>Explication pédagogique<textarea rows={2} value={field(row.explanation)} onChange={(event) => update(index,{explanation:event.target.value})} placeholder="Expliquez pourquoi l’affirmation est vraie ou fausse." /></label></article>)}<button className="add-question" type="button" onClick={() => onChange({...value,statements:[...rows,{id:`statement-${Date.now()}`,text:'',answer:true,explanation:''}]})}>＋ Ajouter une affirmation</button></div>;
}

function DragDropEditor({ value,onChange,visualAllowed }: { value:Record<string,unknown>;onChange:(value:Record<string,unknown>)=>void;visualAllowed:boolean }) {
  const mode = visualAllowed && value.mode === 'visual' ? 'visual' : 'association';
  const targets = contentRows(mode === 'visual' ? value.zones : value.categories);
  const items = contentRows(value.items);
  const rows = Array.from({length:Math.max(targets.length,items.length,2)},(_,index) => ({target:targets[index] ?? {},item:items[index] ?? {}}));
  const emit = (nextTargets:ContentRow[],nextItems:ContentRow[],nextMode = mode) => onChange({...value,mode:nextMode,instruction:field(value.instruction),categories:nextMode === 'association' ? nextTargets : undefined,zones:nextMode === 'visual' ? nextTargets : undefined,items:nextItems});
  const update = (index:number,targetPatch:ContentRow,itemPatch:ContentRow = {}) => {
    const current = rows[index]; const id = field(current.target.id,current.item.category) || `target-${index + 1}`;
    const nextTargets = rows.map((row,rowIndex) => rowIndex === index ? {...row.target,id,...targetPatch} : {...row.target,id:field(row.target.id,row.item.category) || `target-${rowIndex + 1}`});
    const nextItems = rows.map((row,rowIndex) => { const targetId = field(nextTargets[rowIndex].id); return rowIndex === index ? {...row.item,id:field(row.item.id) || `item-${rowIndex + 1}`,category:targetId,...itemPatch} : {...row.item,id:field(row.item.id) || `item-${rowIndex + 1}`,category:targetId}; });
    emit(nextTargets,nextItems);
  };
  const switchMode = (nextMode:'association'|'visual') => emit(rows.map((row,index) => ({...row.target,id:field(row.target.id,row.item.category) || `target-${index + 1}`})),rows.map((row,index) => ({...row.item,id:field(row.item.id) || `item-${index + 1}`,category:field(row.target.id,row.item.category) || `target-${index + 1}`})),nextMode);
  const add = () => { const id = `target-${Date.now()}`; emit([...targets,{id,label:mode === 'visual' ? 'Nouveau visuel' : `Définition ${targets.length + 1}`,description:'',imageUrl:''}],[...items,{id:`item-${Date.now()}`,label:'',category:id,explanation:''}]); };
  const remove = (index:number) => emit(rows.filter((_,rowIndex) => rowIndex !== index).map((row,rowIndex) => ({...row.target,id:field(row.target.id,row.item.category) || `target-${rowIndex + 1}`})),rows.filter((_,rowIndex) => rowIndex !== index).map((row,rowIndex) => ({...row.item,id:field(row.item.id) || `item-${rowIndex + 1}`,category:field(row.target.id,row.item.category) || `target-${rowIndex + 1}`})));
  return <div className="simple-editor drag-drop-editor">{visualAllowed && <div className="editor-mode-switch"><button className={mode === 'association' ? 'active' : ''} type="button" onClick={() => switchMode('association')}><span>↔</span><b>Étiquettes et définitions</b><small>Associer un terme à une explication.</small></button><button className={mode === 'visual' ? 'active' : ''} type="button" onClick={() => switchMode('visual')}><span>▧</span><b>Étiquettes et visuels</b><small>Associer un terme à une image ou une zone.</small></button></div>}<label>Consigne de l’exercice<input value={field(value.instruction)} onChange={(event) => onChange({...value,instruction:event.target.value})} placeholder="Ex. Associez chaque document à sa définition." /></label>{mode === 'visual' && <label>Image générale de fond, facultative<input type="url" value={field(value.imageUrl)} onChange={(event) => onChange({...value,imageUrl:event.target.value})} placeholder="https://…" /></label>}<div className="simple-editor">{rows.map(({target,item},index) => <article className="simple-editor-card association-editor-card" key={field(target.id,item.id) || index}><header><strong>{mode === 'visual' ? `Association visuelle ${index + 1}` : `Association ${index + 1}`}</strong><button type="button" disabled={rows.length <= 2} onClick={() => remove(index)}>Supprimer</button></header><div className="form-row two"><label>Étiquette à déplacer<input required value={field(item.label,item.text)} onChange={(event) => update(index,{}, {label:event.target.value})} placeholder="Ex. Cahier de liaison" /></label><label>{mode === 'visual' ? 'Nom du visuel ou de la zone' : 'Titre court de la destination'}<input required value={field(target.label,target.title)} onChange={(event) => update(index,{label:event.target.value})} placeholder={mode === 'visual' ? 'Ex. Produit inflammable' : `Ex. Définition ${index + 1}`} /></label></div><label>{mode === 'visual' ? 'Description du visuel' : 'Définition à associer'}<textarea required rows={2} value={field(target.description,target.definition,target.text)} onChange={(event) => update(index,{description:event.target.value})} placeholder="Décrivez clairement la destination correcte." /></label>{mode === 'visual' && <div className="form-row"><label>Image de cette zone<input type="url" value={field(target.imageUrl)} onChange={(event) => update(index,{imageUrl:event.target.value})} placeholder="https://…" /></label><label>Position horizontale %<input type="number" min="0" max="100" value={field(target.x)} onChange={(event) => update(index,{x:event.target.value === '' ? undefined : Number(event.target.value)})} /></label><label>Position verticale %<input type="number" min="0" max="100" value={field(target.y)} onChange={(event) => update(index,{y:event.target.value === '' ? undefined : Number(event.target.value)})} /></label></div>}<label>Explication après correction<textarea rows={2} value={field(item.explanation)} onChange={(event) => update(index,{}, {explanation:event.target.value})} placeholder="Expliquez le lien entre l’étiquette et sa destination." /></label></article>)}</div><button className="add-question" type="button" onClick={add}>＋ Ajouter une association</button></div>;
}

function RankingEditor({ value,onChange }: { value:Record<string,unknown>;onChange:(value:Record<string,unknown>)=>void }) {
  const rows = contentRows(value.items);
  const change = (index:number,label:string) => onChange({...value,items:rows.map((row,rowIndex) => rowIndex === index ? {...row,label} : row)});
  const move = (index:number,direction:-1|1) => { const target = index + direction; if (target < 0 || target >= rows.length) return; const next = [...rows]; [next[index],next[target]] = [next[target],next[index]]; onChange({...value,items:next}); };
  return <div className="simple-editor"><p className="editor-help">Saisissez les étapes directement dans l’ordre attendu. Elles seront mélangées pour l’apprenant.</p>{rows.map((row,index) => <article className="list-editor-row" key={String(row.id ?? index)}><span>{index + 1}</span><input required value={field(row.label,row.text)} onChange={(event) => change(index,event.target.value)} placeholder="Ex. Préparer le matériel" /><div><button type="button" disabled={index === 0} onClick={() => move(index,-1)}>↑</button><button type="button" disabled={index === rows.length - 1} onClick={() => move(index,1)}>↓</button><button type="button" disabled={rows.length <= 2} onClick={() => onChange({...value,items:rows.filter((_,rowIndex) => rowIndex !== index)})}>×</button></div></article>)}<button className="add-question" type="button" onClick={() => onChange({...value,items:[...rows,{id:`step-${Date.now()}`,label:''}]})}>＋ Ajouter une étape</button></div>;
}

function RevisionCardsEditor({ value,onChange }: { value:Record<string,unknown>;onChange:(value:Record<string,unknown>)=>void }) {
  const rows = contentRows(value.cards);
  const update = (index:number,patch:ContentRow) => onChange({...value,cards:rows.map((row,rowIndex) => rowIndex === index ? {...row,...patch} : row)});
  return <div className="simple-editor">{rows.map((row,index) => <article className="simple-editor-card" key={String(row.id ?? index)}><header><strong>Carte {index + 1}</strong><button type="button" disabled={rows.length <= 1} onClick={() => onChange({...value,cards:rows.filter((_,rowIndex) => rowIndex !== index)})}>Supprimer</button></header><div className="form-row two"><label>Recto · question<textarea required rows={2} value={field(row.front,row.label)} onChange={(event) => update(index,{front:event.target.value})} placeholder="Ex. Que signifie EPI ?" /></label><label>Verso · réponse<textarea required rows={2} value={field(row.back,row.answer)} onChange={(event) => update(index,{back:event.target.value})} placeholder="Ex. Équipement de protection individuelle" /></label></div></article>)}<button className="add-question" type="button" onClick={() => onChange({...value,cards:[...rows,{id:`card-${Date.now()}`,front:'',back:''}]})}>＋ Ajouter une carte</button></div>;
}

function TypedPromptsEditor({ value,onChange }: { value:Record<string,unknown>;onChange:(value:Record<string,unknown>)=>void }) {
  const rows = contentRows(value.prompts);
  const update = (index:number,patch:ContentRow) => onChange({...value,prompts:rows.map((row,rowIndex) => rowIndex === index ? {...row,...patch} : row)});
  return <div className="simple-editor">{rows.map((row,index) => <article className="simple-editor-card" key={String(row.id ?? index)}><header><strong>Question {index + 1}</strong><button type="button" disabled={rows.length <= 1} onClick={() => onChange({...value,prompts:rows.filter((_,rowIndex) => rowIndex !== index)})}>Supprimer</button></header><label>Question<input required value={field(row.question)} onChange={(event) => update(index,{question:event.target.value})} /></label><label>Réponse attendue<input required value={field(row.answer)} onChange={(event) => update(index,{answer:event.target.value})} /></label><label>Explication<textarea rows={2} value={field(row.explanation)} onChange={(event) => update(index,{explanation:event.target.value})} /></label></article>)}<button className="add-question" type="button" onClick={() => onChange({...value,prompts:[...rows,{id:`prompt-${Date.now()}`,question:'',answer:'',explanation:''}]})}>＋ Ajouter une question</button></div>;
}

function QuestionWheelEditor({ value,onChange }: { value:Record<string,unknown>;onChange:(value:Record<string,unknown>)=>void }) {
  const rows = contentRows(value.sectors);
  return <div className="simple-editor"><p className="editor-help">Chaque secteur de la roue contient une question ou un défi à tirer au hasard.</p>{rows.map((row,index) => <article className="list-editor-row" key={String(row.id ?? index)}><span>{index + 1}</span><input required value={field(row.label,row.text)} onChange={(event) => onChange({...value,sectors:rows.map((item,itemIndex) => itemIndex === index ? {...item,label:event.target.value} : item)})} placeholder="Ex. Pourquoi faut-il baliser la zone ?" /><button type="button" disabled={rows.length <= 2} onClick={() => onChange({...value,sectors:rows.filter((_,rowIndex) => rowIndex !== index)})}>×</button></article>)}<button className="add-question" type="button" onClick={() => onChange({...value,sectors:[...rows,{id:`sector-${Date.now()}`,label:''}]})}>＋ Ajouter une question</button></div>;
}

function LivePollEditor({ value,onChange }: { value:Record<string,unknown>;onChange:(value:Record<string,unknown>)=>void }) {
  const options = Array.isArray(value.options) ? value.options.map(String) : [];
  return <div className="simple-editor"><label>Question du sondage<input required value={field(value.question)} onChange={(event) => onChange({...value,question:event.target.value})} placeholder="Ex. Quelle notion souhaitez-vous retravailler ?" /></label>{options.map((option,index) => <article className="list-editor-row" key={index}><span>{String.fromCharCode(65 + index)}</span><input required value={option} onChange={(event) => onChange({...value,options:options.map((item,itemIndex) => itemIndex === index ? event.target.value : item)})} placeholder={`Choix ${index + 1}`} /><button type="button" disabled={options.length <= 2} onClick={() => onChange({...value,options:options.filter((_,itemIndex) => itemIndex !== index)})}>×</button></article>)}<button className="add-question" type="button" onClick={() => onChange({...value,options:[...options,'']})}>＋ Ajouter un choix</button></div>;
}

function contentRows(value:unknown):ContentRow[] { return Array.isArray(value) ? value.filter((item):item is ContentRow => Boolean(item && typeof item === 'object' && !Array.isArray(item))) : []; }
function field(...values:unknown[]):string { const value = values.find((item) => typeof item === 'string' || typeof item === 'number'); return value === undefined ? '' : String(value); }

function ScenarioEditor({ value,onChange }: { value:ScenarioContent;onChange:(value:ScenarioContent)=>void }) {
  const minimumScenes = value.mode === 'progressive' || value.mode === 'successive' ? 3 : 1;
  const updateScene = (index:number,patch:Partial<ScenarioScene>) => onChange({...value,scenes:value.scenes.map((scene,sceneIndex) => sceneIndex === index ? {...scene,...patch} : scene)});
  const moveScene = (index:number,direction:-1|1) => { const target = index + direction; if (target < 0 || target >= value.scenes.length) return; const scenes = [...value.scenes]; [scenes[index],scenes[target]] = [scenes[target],scenes[index]]; onChange({...value,scenes:linkScenarioScenes(scenes)}); };
  const removeScene = (index:number) => { if (value.scenes.length <= minimumScenes) return; onChange({...value,scenes:linkScenarioScenes(value.scenes.filter((_,sceneIndex) => sceneIndex !== index))}); };
  const addScene = () => { if (value.scenes.length >= 6) return; const number = value.scenes.length + 1; const nextId = `scene-${Date.now()}`; const next:ScenarioScene = {id:nextId,title:`Nouvelle situation ${number}`,location:'Lieu de travail',moment:'Pendant l’intervention',learnerRole:'Professionnel en situation',people:[],context:'Décrivez ce qui se passe concrètement.',problem:'Précisez le problème à résoudre.',constraints:[],mission:'Choisir une réaction et justifier sa décision.',objective:'Adapter sa conduite à la situation.',competencies:[],observationCriteria:[],usefulInformation:[],documents:[],question:'Quelle réaction professionnelle choisissez-vous ?',choices:[0,1,2].map((score) => ({id:`choice-${Date.now()}-${score}`,text:`Décision ${score + 1}`,score:score as 0|1|2,consequence:'Décrivez la conséquence observable.',positivePoints:[],risks:[],recommendedConduct:'Précisez la conduite professionnelle recommandée.',explanation:'Expliquez pourquoi cette décision est adaptée ou non.',nextSceneId:null}))}; onChange({...value,scenes:linkScenarioScenes([...value.scenes,next])}); };
  return <div className="scenario-editor"><div className="scenario-editor-note"><span>{value.scenes.length}</span><p><strong>Modèle métier prêt à adapter</strong>Chaque scène comporte un contexte, une mission, 3 à 4 décisions plausibles et un retour noté sur 2. Vous pouvez ajouter, déplacer ou supprimer les scènes sans toucher au code.</p></div><label>Type de parcours<select value={value.mode} onChange={(event) => { const mode = event.target.value as ScenarioContent['mode']; const required = mode === 'progressive' || mode === 'successive' ? 3 : 1; const scenes = value.scenes.length >= required ? value.scenes : [...value.scenes,...cloneScenario(SCENARIO_EXAMPLE_CONTENT).scenes.slice(value.scenes.length,required)]; onChange({...value,mode,progressive:mode === 'progressive' || mode === 'successive',scenes:linkScenarioScenes(scenes)}); }}><option value="single">Une seule mise en situation</option><option value="independent">Situations indépendantes</option><option value="progressive">Parcours progressif</option><option value="successive">Décisions successives</option><option value="case-study">Étude de cas</option><option value="final-assessment">Évaluation finale</option></select></label><div className="form-row two"><label>Moment du feedback<select value={value.feedbackTiming} onChange={(event) => onChange({...value,feedbackTiming:event.target.value as ScenarioContent['feedbackTiming']})}><option value="immediate">Après chaque décision</option><option value="deferred">Au bilan final</option></select></label><label>Affichage du score<select value={value.scoreMode} onChange={(event) => onChange({...value,scoreMode:event.target.value as ScenarioContent['scoreMode']})}><option value="points">Points</option><option value="skills">Compétences</option><option value="hidden">Score masqué</option></select></label></div><div className="scenario-output-checks"><label><input type="checkbox" checked={value.showHints} onChange={(event) => onChange({...value,showHints:event.target.checked})} />Afficher les indices utiles</label><label><input type="checkbox" checked={value.simplifiedFrench} onChange={(event) => onChange({...value,simplifiedFrench:event.target.checked})} />Français simplifié</label><label><input type="checkbox" checked={value.addImages} onChange={(event) => onChange({...value,addImages:event.target.checked})} />Prévoir des visuels</label></div>{value.scenes.map((scene,index) => <details className="scenario-scene-editor" open={index === 0} key={scene.id}><summary><span>Situation {index + 1}</span><strong>{scene.title}</strong><small>{scene.choices.length} décisions</small></summary><div className="scenario-scene-editor-body"><div className="scenario-editor-actions"><button type="button" disabled={index === 0} onClick={() => moveScene(index,-1)}>↑ Monter</button><button type="button" disabled={index === value.scenes.length - 1} onClick={() => moveScene(index,1)}>↓ Descendre</button><button type="button" disabled={value.scenes.length <= minimumScenes} onClick={() => removeScene(index)}>Supprimer</button></div><div className="form-row two"><label>Titre de la situation<input value={scene.title} onChange={(event) => updateScene(index,{title:event.target.value})} /></label><label>Lieu<input value={scene.location} onChange={(event) => updateScene(index,{location:event.target.value})} /></label><label>Moment<input value={scene.moment} onChange={(event) => updateScene(index,{moment:event.target.value})} /></label><label>Rôle de l’apprenant<input value={scene.learnerRole} onChange={(event) => updateScene(index,{learnerRole:event.target.value})} /></label></div><label>Contexte<textarea rows={3} value={scene.context} onChange={(event) => updateScene(index,{context:event.target.value})} /></label><label>Problème à résoudre<textarea rows={2} value={scene.problem} onChange={(event) => updateScene(index,{problem:event.target.value})} /></label><label>Dialogue ou consigne orale<textarea rows={2} value={scene.dialogue ?? ''} onChange={(event) => updateScene(index,{dialogue:event.target.value})} /></label><div className="form-row two"><LineList label="Personnes présentes, une par ligne" value={scene.people} onChange={(people) => updateScene(index,{people})} /><LineList label="Contraintes, une par ligne" value={scene.constraints} onChange={(constraints) => updateScene(index,{constraints})} /></div><div className="form-row two"><label>Mission<textarea rows={2} value={scene.mission} onChange={(event) => updateScene(index,{mission:event.target.value})} /></label><label>Objectif pédagogique<textarea rows={2} value={scene.objective} onChange={(event) => updateScene(index,{objective:event.target.value})} /></label></div><div className="form-row two"><LineList label="Compétences, une par ligne" value={scene.competencies} onChange={(competencies) => updateScene(index,{competencies})} /><LineList label="Points à observer, un par ligne" value={scene.observationCriteria} onChange={(observationCriteria) => updateScene(index,{observationCriteria})} /></div><div className="form-row two"><LineList label="Informations utiles ou indices" value={scene.usefulInformation} onChange={(usefulInformation) => updateScene(index,{usefulInformation})} /><LineList label="Documents de travail" value={scene.documents} onChange={(documents) => updateScene(index,{documents})} /></div><label>Question posée à l’apprenant<input value={scene.question} onChange={(event) => updateScene(index,{question:event.target.value})} /></label><div className="scenario-choice-editors">{scene.choices.map((choice,choiceIndex) => <article key={choice.id}><header><strong>Décision {String.fromCharCode(65 + choiceIndex)}</strong><label>Score<select value={choice.score} onChange={(event) => updateScene(index,{choices:scene.choices.map((item,itemIndex) => itemIndex === choiceIndex ? {...item,score:Number(event.target.value) as 0|1|2} : item)})}><option value="0">0 · à risque</option><option value="1">1 · partielle</option><option value="2">2 · recommandée</option></select></label></header><label>Réponse proposée<textarea rows={2} value={choice.text} onChange={(event) => updateScene(index,{choices:scene.choices.map((item,itemIndex) => itemIndex === choiceIndex ? {...item,text:event.target.value} : item)})} /></label><label>Conséquence<textarea rows={2} value={choice.consequence} onChange={(event) => updateScene(index,{choices:scene.choices.map((item,itemIndex) => itemIndex === choiceIndex ? {...item,consequence:event.target.value} : item)})} /></label><div className="form-row two"><LineList label="Points positifs" value={choice.positivePoints} onChange={(positivePoints) => updateScene(index,{choices:scene.choices.map((item,itemIndex) => itemIndex === choiceIndex ? {...item,positivePoints} : item)})} /><LineList label="Risques" value={choice.risks} onChange={(risks) => updateScene(index,{choices:scene.choices.map((item,itemIndex) => itemIndex === choiceIndex ? {...item,risks} : item)})} /></div><label>Conduite recommandée<textarea rows={2} value={choice.recommendedConduct} onChange={(event) => updateScene(index,{choices:scene.choices.map((item,itemIndex) => itemIndex === choiceIndex ? {...item,recommendedConduct:event.target.value} : item)})} /></label><label>Explication pédagogique<textarea rows={2} value={choice.explanation} onChange={(event) => updateScene(index,{choices:scene.choices.map((item,itemIndex) => itemIndex === choiceIndex ? {...item,explanation:event.target.value} : item)})} /></label>{scene.choices.length > 3 && <button className="scenario-remove-choice" type="button" onClick={() => updateScene(index,{choices:scene.choices.filter((_,itemIndex) => itemIndex !== choiceIndex)})}>Retirer cette décision</button>}</article>)}</div>{scene.choices.length < 4 && <button className="add-question" type="button" onClick={() => updateScene(index,{choices:[...scene.choices,{id:`choice-${Date.now()}`,text:'Nouvelle décision',score:1,consequence:'Décrivez la conséquence.',positivePoints:[],risks:[],recommendedConduct:'Précisez la conduite recommandée.',explanation:'Expliquez le raisonnement professionnel.',nextSceneId:null}]})}>＋ Ajouter une décision</button>}</div></details>)}<button className="add-question" type="button" disabled={value.scenes.length >= 6} onClick={addScene}>＋ Ajouter une situation ({value.scenes.length}/6)</button><section className="scenario-debrief-editor"><strong>Bilan final</strong><label>Synthèse<textarea rows={3} value={value.debrief.summary} onChange={(event) => onChange({...value,debrief:{...value.debrief,summary:event.target.value}})} /></label><LineList label="Bonnes pratiques, une par ligne" value={value.debrief.bestPractices} onChange={(bestPractices) => onChange({...value,debrief:{...value.debrief,bestPractices}})} /><LineList label="Points à revoir, un par ligne" value={value.debrief.pointsToReview} onChange={(pointsToReview) => onChange({...value,debrief:{...value.debrief,pointsToReview}})} /><LineList label="Questions du formateur, une par ligne" value={value.debrief.trainerQuestions} onChange={(trainerQuestions) => onChange({...value,debrief:{...value.debrief,trainerQuestions}})} /></section></div>;
}

function LineList({ label,value,onChange }: { label:string;value:string[];onChange:(value:string[])=>void }) { return <label>{label}<textarea rows={3} value={value.join('\n')} onChange={(event) => onChange(event.target.value.split('\n').map((item) => item.trim()).filter(Boolean))} /></label>; }
function cloneScenario(value:ScenarioContent):ScenarioContent { return JSON.parse(JSON.stringify(value)) as ScenarioContent; }
function linkScenarioScenes(scenes:ScenarioScene[]):ScenarioScene[] { return scenes.map((scene,index) => ({...scene,choices:scene.choices.map((choice) => ({...choice,nextSceneId:scenes[index + 1]?.id ?? null}))})); }

function starterContent(type: ActivityType): Record<string,unknown> {
  const items = [{label:'Préparer le matériel',category:'Avant'},{label:'Baliser la zone',category:'Avant'},{label:'Contrôler le résultat',category:'Après'}];
  if (type === 'true-false') return { statements:[{text:'Les produits chimiques peuvent être mélangés pour gagner du temps.',answer:false,explanation:'Un mélange peut produire une réaction dangereuse.'}] };
  if (type === 'word-search') return { grid:['BALISAGE','PRODUITS','SECURITE','MATERIEL'],words:['BALISAGE','SECURITE'] };
  if (type === 'crossword') return { grid:['....#','.#...','.....'],clues:[{label:'Protection individuelle'},{label:'Signalement d’une zone humide'}] };
  if (type === 'hangman') return { words:['BALISAGE'] };
  if (['flip-tiles','revision-cards','random-cards','memory-cards'].includes(type)) return { cards:[{front:'Que signifie EPI ?',back:'Équipement de protection individuelle'},{front:'Pourquoi baliser ?',back:'Pour prévenir les chutes'}] };
  if (type === 'pair-or-not') return { cards:[{front:'Gants',back:'Protection des mains',pair:'epi'},{front:'Protection des mains',back:'Gants',pair:'epi'},{front:'Balai',back:'Matériel manuel',pair:'materiel'}] };
  if (type === 'type-answer') return { prompts:[{question:'Quel équipement protège les mains ?',answer:'des gants',explanation:'Les gants adaptés protègent du contact avec les produits.'}] };
  if (type === 'interactive-image') return { imageUrl:'',hotspots:[{label:'Poignée',answer:'Permet de guider la machine'},{label:'Disque',answer:'Agit sur le sol'}] };
  if (type === 'scenario') return cloneScenario(SCENARIO_EXAMPLE_CONTENT);
  if (type === 'live-poll') return { question:'Quelle notion souhaitez-vous retravailler ?',options:['Sécurité','Dosage','Matériel'] };
  if (type === 'external-game') return JSON.parse(JSON.stringify(DEFAULT_EXTERNAL_GAME_CONTENT)) as Record<string,unknown>;
  if (type === 'voice-coach') return normalizeVoiceCoachContent({learningLanguage:'anglais',explanationLanguage:'français',cefrLevel:'A1',topic:'Se présenter dans un contexte professionnel',conversationMode:'guided-dialogue',objectives:['Se présenter simplement','Poser une question courte'],vocabulary:['hello','name','job'],phrases:['My name is…','What is your name?'],customQuestions:['What is your name?','What is your job?'],repeatItems:['Hello, my name is…','Nice to meet you.'],coachScript:'Faire écouter chaque phrase, demander à l’apprenant de la répéter, corriger un seul point puis poser les questions dans l’ordre.',maxDurationMinutes:10});
  if (type === 'challenge-wheel' || type === 'question-wheel') return { sectors:[{label:type === 'question-wheel' ? 'Pourquoi faut-il baliser la zone ?' : 'Montrez le bon geste de balisage'},{label:type === 'question-wheel' ? 'Comment vérifier un dosage ?' : 'Expliquez le dosage'},{label:type === 'question-wheel' ? 'Quels sont les trois EPI utiles ?' : 'Citez trois EPI'},{label:type === 'question-wheel' ? 'Quel risque voyez-vous ?' : 'Repérez un risque'}] };
  if (type === 'maze') return { cells:[{label:'Départ',correct:true},{label:'Baliser',correct:true},{label:'Mélanger',correct:false},{label:'Contrôler',correct:true}] };
  if (type === 'flying-fruits') return { prompts:[{question:'Quel choix protège les mains ?',options:[{label:'Les gants',correct:true},{label:'Le parfum',correct:false},{label:'La cire',correct:false}]}] };
  if (type === 'drag-drop') return { mode:'association',instruction:'Associez chaque document professionnel à sa définition.',categories:[{id:'definition-1',label:'Définition 1',description:'Décrit précisément les tâches confiées à l’agent.'},{id:'definition-2',label:'Définition 2',description:'Permet de consigner les informations et difficultés rencontrées sur le site.'},{id:'definition-3',label:'Définition 3',description:'Précise l’organisation et les périodes de réalisation des travaux.'}],items:[{id:'fiche-poste',label:'Fiche de poste',category:'definition-1',explanation:'La fiche de poste décrit les missions et tâches du salarié.'},{id:'cahier-liaison',label:'Cahier de liaison',category:'definition-2',explanation:'Le cahier de liaison assure la transmission entre les acteurs du site.'},{id:'planning',label:'Planning des travaux',category:'definition-3',explanation:'Le planning organise les interventions dans le temps.'}] };
  if (type === 'matching') return { mode:'association',instruction:'Associez chaque notion à sa définition.',categories:[{id:'pair-1',label:'Définition 1',description:'Équipement porté pour limiter l’exposition à un risque.'},{id:'pair-2',label:'Définition 2',description:'Signalisation destinée à prévenir les personnes d’un danger temporaire.'}],items:[{id:'notion-1',label:'EPI',category:'pair-1',explanation:'Un EPI protège individuellement le professionnel.'},{id:'notion-2',label:'Balisage',category:'pair-2',explanation:'Le balisage matérialise et signale une zone dangereuse.'}] };
  if (type === 'ranking') return { items:[{id:'step-1',label:'Préparer le matériel'},{id:'step-2',label:'Baliser la zone'},{id:'step-3',label:'Réaliser l’intervention'},{id:'step-4',label:'Contrôler le résultat'}] };
  if (type === 'categories') return { categories:[{label:'Avant'},{label:'Après'}],items };
  if (['spell-word','anagram'].includes(type)) return { word:'SECURITE',items:'SECURITE'.split('').map((letter) => ({label:letter})) };
  if (type === 'unravel') return { sentence:'Je balise la zone avant de laver',items:'Je balise la zone avant de laver'.split(' ').map((word) => ({label:word})) };
  return { categories:[{label:'Avant'},{label:'Après'}],zones:[{label:'Avant'},{label:'Après'}],items };
}
